 for(const[hx0,dir]of[[31,-1],[43,1]]){for(let i=0;i<4;i++)set(hx0+dir*i,3-i,i<2?'w':'v')}
 for(let x=6;x<29;x+=4){const k=Math.sqrt(Math.max(0,1-((x-19)/17)**2));const ty=Math.round(18-11*k);set(x,ty-1,'x');set(x,ty-2,'x');set(x,ty-3,'O');set(x,ty-4,'O');set(x+1,ty-1,'z');set(x+1,ty-2,'z');set(x-1,ty-1,'z')}
