function renderPal(rows,pal){const w=rows[0].length,h=rows.length;const c=document.createElement('canvas');c.width=w+2;c.height=h+2;const x=c.getContext('2d');const img=x.createImageData(w+2,h+2);
 const hx=s=>[1,3,5].map(k=>parseInt(s.slice(k,k+2),16));
 for(let j=0;j<h;j++)for(let i=0;i<w;i++){const ch=rows[j][i];if(ch==='.'||!pal[ch])continue;const rgb=hx(pal[ch]);const o=((j+1)*(w+2)+i+1)*4;img.data[o]=rgb[0];img.data[o+1]=rgb[1];img.data[o+2]=rgb[2];img.data[o+3]=255}
 x.putImageData(img,0,0);return c}
function bossFrames(name){const R=BOSS_ART[name],w=R[0].length,blank='.'.repeat(w);const a=[blank,...R],b=[...R,blank];const A=renderPal(a,BOSS_ART.pal),Bf=renderPal(b,BOSS_ART.pal);return[A,Bf,A,Bf,A,Bf]}
